/* ── File helper: first non-empty line with fallback ────────── */
static bool read_first_line(const char *primary, const char *fallback,
                            char *buf, size_t buflen)
{
    FILE *fp = fopen(primary, "r");
    if (fp == NULL && fallback != NULL) {
        fp = fopen(fallback, "r");
    }
    if (fp == NULL) {
        if (buflen > 0) buf[0] = '\0';
        return false;
    }

    bool ok = false;
    while (fgets(buf, (int)buflen, fp) != NULL) {
        size_t n = strlen(buf);
        while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) {
            buf[--n] = '\0';
        }
        if (n > 0) {
            ok = true;
            break;
        }
    }
    fclose(fp);
    if (!ok && buflen > 0) buf[0] = '\0';
    return ok;
}

